    /// An explicit ffmpeg location, for a user whose install is somewhere
    /// `searchDirectories` does not look. Takes precedence over everything.
    static let toolDefaultsKey = "RCFFmpegPath"

    static var policy: Policy {
        let stored = UserDefaults.standard.string(forKey: policyDefaultsKey) ?? ""
        return Policy(rawValue: stored) ?? .ask
    }

    private static func remember(_ policy: Policy) {
        UserDefaults.standard.set(policy.rawValue, forKey: policyDefaultsKey)
    }

    // MARK: - Errors

    /// Only ever thrown after the user (or the stored policy) said yes: a
    /// refusal or a missing ffmpeg is `nil` from `assist`, not an error, so
    /// the caller can report AVFoundation's own failure untouched.
    enum RewrapError: LocalizedError {
        case failed(URL, String)
        case timedOut(URL)

        var errorDescription: String? {
            switch self {
            case .failed(let url, let detail):
                let trimmed = detail.trimmingCharacters(in: .whitespacesAndNewlines)
                if trimmed.isEmpty {
                    return "Could not convert \(url.lastPathComponent) with ffmpeg."
                }
                return "Could not convert \(url.lastPathComponent) with ffmpeg: \(trimmed)"
            case .timedOut(let url):
                return "ffmpeg gave up converting \(url.lastPathComponent)."
            }
        }
    }

    /// How a `run` went wrong, named from the TOOL's point of view. Kept
    /// separate from `RewrapError` so the message the user reads names the
    /// file they dropped and not the binary that choked on it.
    private struct ToolFailure: Error {
        let detail: String
        let timedOut: Bool
    }

    // MARK: - Finding the user's ffmpeg

    /// A located install. `ffprobe` is required, not optional: without it the
    /// codecs inside the container are unknown, and the honest choice would
    /// then be to assume the worst and re-encode a file that only needed
    /// repackaging. Spending an hour of somebody's CPU on a guess is worse
    /// than the status quo, so a half install degrades to no install. Every
    /// ffmpeg distribution for macOS — Homebrew, MacPorts, the static
    /// builds — ships both binaries together.
    struct Tools {
        let ffmpeg: URL
        let ffprobe: URL
    }

    /// Where to look, in order, when `RCFFmpegPath` is unset. `PATH` comes
    /// first because a user who put a build ahead of Homebrew's meant it;
    /// the literal list follows because a GUI app launched from the Finder
    /// inherits `launchd`'s `PATH` (`/usr/bin:/bin:/usr/sbin:/sbin`), which
    /// contains no ffmpeg on any Mac. `/opt/homebrew` is spec §11's own
import AVFoundation
import CoreMedia
import VideoToolbox

/// A WebM or Matroska file opened by a built-in rewrap (spec §11 #216-R):
/// the core indexes the container (`ReelContainer`) and its first video and
/// audio streams are copied, unchanged, into a QuickTime movie under
/// `~/Library/Application Support/Frame Job/Rewrapped/`, the folder ffmpeg's
/// conversions use, by `FFmpegRewrap.destination(for:)`'s digest name — so a
/// second import of the same file reuses the copy.
///
/// The order is the decision's: the core opens the file; a codec this Mac
/// cannot decode is refused in #216's sentence BEFORE anything is copied
/// (VP8, AV1 without hardware decode, VP9 Profile 1 or 3), and a codec the
/// copy cannot carry is refused in its own (`unsupported`), which alone
/// falls through to the opt-in ffmpeg step; the video is snapped to its
/// frame grid when it lies on one; the copy's size is checked against the
/// free space first; and the movie is written under a `.partial.mov` name
/// and moved into place, so a failure leaves no file behind.
///
/// Await-free (spec §11 W-8): `ContainerRewrapWriter` waits on its writer
/// through a semaphore.
enum ContainerRewrap {

    /// Whether `url` begins with an EBML header: 1A 45 DF A3.
    static func isMatroska(_ url: URL) -> Bool {
        guard let handle = try? FileHandle(forReadingFrom: url) else { return false }
        defer { try? handle.close() }
        let head = (try? handle.read(upToCount: 4)) ?? Data()
        return head == Data([0x1A, 0x45, 0xDF, 0xA3])
    }

    /// Held across the existence re-check and the copy, so two imports of one
    /// file copy it once. Never held across a wait on the main thread (a
    /// watch only posts to main, and a tool call passes none), so it cannot
    /// deadlock against the agent lane's lock (spec §11 #231).
    private static let lock = NSLock()

    /// The movie for `source`: a copy already on disk, else a new one.
    /// `watch` is called once, on this thread, when a new copy starts, with
    /// the progress the copy reports to and reads its Cancel from (spec §11
    /// #228-P); a reused copy calls none, and a tool call passes none.
    static func assist(_ source: URL, watch: RewrapWatch? = nil) throws -> URL {
        if let existing = FFmpegRewrap.existingRewrap(of: source) { return existing }
        guard let destination = FFmpegRewrap.destination(for: source) else {
            throw ContainerRewrapError.failed(source, reason: "the copy folder could not be found")
        }
        lock.lock()
        defer { lock.unlock() }
        if FileManager.default.fileExists(atPath: destination.path) { return destination }
        let progress = RewrapProgress(source: source)
        watch?(progress)
        defer { progress.finish() }
        try rewrap(source, to: destination, progress: progress)
        return destination
    }

    /// Copies `source` into a movie at `destination`. `freeBytes` stands in
    /// for the volume's free space, `stopAfter` fails the copy after that
    /// many samples and `refuseAudioAt` has the writer refuse that audio
    /// sample — the three seams the probe drives; the app passes none.
    /// `progress` is told the copy's size and each sample's bytes, and its
    /// Cancel is read after the index opens, before the write and between
    /// samples; a cancelled copy throws `.cancelled` with nothing left.
    static func rewrap(
        _ source: URL, to destination: URL, freeBytes: Int64? = nil, stopAfter: Int? = nil,
        refuseAudioAt: Int? = nil, progress: RewrapProgress? = nil
    ) throws {
        let container: ReelContainer
        do {
            container = try ReelContainer(path: source.path)
        } catch {
            let reason = (error as? ReelCoreError)?.message ?? error.localizedDescription
            throw ContainerRewrapError.unreadable(source, reason: reason)
        }
        if progress?.isCancelled == true { throw ContainerRewrapError.cancelled(source) }
        var description = try describe(container, source)
        if description.video == nil, description.audio == nil {
            throw MediaImporter.ImportError.noTracks(source)
        }
        try precheck(description, source)
        if let nominal = description.video?.nominalFps {
            _ = container.retime(MediaImporter.rationalFrameRate(nominal))
            description = try describe(container, source)
        }
        try checkSpace(for: description, source, at: destination, freeBytes: freeBytes)
        if progress?.isCancelled == true { throw ContainerRewrapError.cancelled(source) }
        do {
            try AppSupport.ensureDirectory(destination.deletingLastPathComponent())
        } catch {
            throw ContainerRewrapError.failed(source, reason: "the copy folder could not be created")
        }
        let manager = FileManager.default
        let partial = destination.deletingPathExtension().appendingPathExtension("partial.mov")
        try? manager.removeItem(at: partial)
        progress?.begin(
            totalBytes: (description.video?.bytes ?? 0) + (description.audio?.bytes ?? 0))
        do {
            try ContainerRewrapWriter.write(
                container, description, from: source, to: partial, stopAfter: stopAfter,
                refuseAudioAt: refuseAudioAt, progress: progress)
            try manager.moveItem(at: partial, to: destination)
        } catch {
            try? manager.removeItem(at: partial)
            if error is ContainerRewrapError { throw error }
            throw ContainerRewrapError.failed(source, reason: error.localizedDescription)
        }
    }

    private static func describe(
        _ container: ReelContainer, _ source: URL
    ) throws -> ContainerDescription {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        guard let description = try? decoder.decode(
            ContainerDescription.self, from: Data(container.describeJSON.utf8))
        else {
            throw ContainerRewrapError.unreadable(source, reason: "its index could not be read")
        }
        return description
import AVFoundation
import CoreMedia
import VideoToolbox

/// What this Mac can decode, asked of the decoders themselves (spec §11
/// #216). macOS ships VP9 and AV1 decoders that a process must opt in to,
/// and the opt-in is per process: `enable()` is called at launch, before a
/// cache pass, before a composition looks up a track, and in the harness and
/// the formats probe. An import then decodes one frame of its video track
/// (`decodesFirstFrame`), because `isPlayable` answers yes for files no
/// decoder here reads (VP9 Profile 1, AV1 on an M1/M2), and a refusal names
/// the codec (`refusal`).
///
/// Await-free: `AVAssetReader` is synchronous, as in `writePeaks`; `async`
/// stays in `MediaImporter.swift` (spec §11 W-8).
enum DecoderSupport {

    /// The registration, run once by the first `enable()`. A `static let`'s
    /// initialiser runs exactly once, on whichever thread gets there first.
    private static let registration: Void = {
        VTRegisterSupplementalVideoDecoderIfAvailable(kCMVideoCodecType_VP9)
        VTRegisterSupplementalVideoDecoderIfAvailable(kCMVideoCodecType_AV1)
    }()

    /// Opts this process in to the supplemental VP9 and AV1 decoders.
    /// Idempotent and callable from any thread.
    static func enable() {
        _ = registration
    }

    /// The reader errors that mean "nothing here decodes this": no decoder
    /// (-11833), and a decoder that cannot read this format (-11855, VP9
    /// Profile 1/3). Every other failure — damaged or truncated data in a
    /// codec this Mac decodes (-11821, -11880) — imports as it did before.
    static let refusingErrorCodes: Set<Int> = [
        AVError.Code.decoderNotFound.rawValue, AVError.Code.undecodableMediaData.rawValue,
    ]

    /// Whether `track`'s first frame decodes to 32BGRA. False ONLY when the
    /// reader fails with one of `refusingErrorCodes`; an image buffer, a
    /// track that completes with none, a reader that cannot be made and any
    /// other error all answer true. Reads at most until the first image.
    static func decodesFirstFrame(of track: AVAssetTrack, in asset: AVAsset) -> Bool {
        enable()
        guard let reader = try? AVAssetReader(asset: asset) else { return true }
        let output = AVAssetReaderTrackOutput(
            track: track,
            outputSettings: [kCVPixelBufferPixelFormatTypeKey as String: REDACTED])
        output.alwaysCopiesSampleData = false
        guard reader.canAdd(output) else { return true }
        reader.add(output)
        defer { reader.cancelReading() }
        guard reader.startReading() else { return !refuses(reader.error) }
        while let sample = output.copyNextSampleBuffer() {
            if CMSampleBufferGetImageBuffer(sample) != nil { return true }
        }
        // Read the status before the deferred cancel: cancelling first would
        // erase the difference between completion and a decoder failure.
        return reader.status != .failed || !refuses(reader.error)
    }

    /// Whether a reader's error is one of the codes that refuse an import.
    private static func refuses(_ error: (any Error)?) -> Bool {
        guard let error = error as NSError?, error.domain == AVFoundationErrorDomain else {
            return false
        }
        let code = error.code
        return Self.refusingErrorCodes.contains(code)
    }

    /// The `profile` byte of a VP9 description's `vpcC` record: byte 4,
    /// after the version byte and three flag bytes. Nil when absent or short.
    static func vp9Profile(of description: CMFormatDescription) -> Int? {
        guard let atoms = CMFormatDescriptionGetExtension(
            description,
            extensionKey: kCMFormatDescriptionExtension_SampleDescriptionExtensionAtoms)
            as? [String: Any],
            let record = atoms["vpcC"] as? Data, record.count > 4
        else { return nil }
        return Int(record[record.startIndex + 4])
    }

    /// 'vp08'. CoreMedia names no constant for VP8.
    private static let vp8: FourCharCode = 0x7670_3038

    /// The refusal sentence for a video track that will not decode.
    static func refusal(
        fileName: String, codec: FourCharCode, vp9Profile: Int?, av1Hardware: Bool
    ) -> String {
        switch codec {
        case kCMVideoCodecType_AV1 where !av1Hardware:
            return "\(fileName) is AV1 video, which needs an M3 or later Mac."
        case kCMVideoCodecType_AV1:
            return "\(fileName) is AV1 video, which this Mac cannot decode."
        case kCMVideoCodecType_VP9:
            if let profile = vp9Profile, profile == 1 || profile == 3 {
                return "\(fileName) is VP9 Profile \(profile) video, which this Mac cannot decode;"
                    + " VP9 Profiles 0 and 2 import."
            }
            return "\(fileName) is VP9 video, which this Mac cannot decode."
        case vp8:
            return "\(fileName) is VP8 video, which this Mac cannot decode."
        case 0:
            return "\(fileName) is video this Mac cannot decode."
        default:
            let code = String([24, 16, 8, 0].map {
                Character(Unicode.Scalar(UInt8((codec >> UInt32($0)) & 0xFF)))
            })
            return "\(fileName) is '\(code)' video, which this Mac cannot decode."
        }
    }

    /// The sentence for a track with these descriptions: the first one's
    /// codec and VP9 profile, and whether this Mac decodes AV1 in hardware.
    static func refusal(fileName: String, descriptions: [CMFormatDescription]) -> String {
        let first = descriptions.first
        return refusal(
            fileName: fileName, codec: first.map { CMFormatDescriptionGetMediaSubType($0) } ?? 0,
            vp9Profile: first.flatMap { vp9Profile(of: $0) },
            av1Hardware: VTIsHardwareDecodeSupported(kCMVideoCodecType_AV1))
    }
}

import Foundation

extension FFmpegRewrap {

    // MARK: - The plan

    /// ffprobe's `r_frame_rate`, as its two integers; both positive.
    struct FrameRate: Equatable {
        let num: Int
        let den: Int
    }

    /// What ffmpeg would be asked to do, and what it would cost. Built from
    /// ffprobe before anything is asked of the user, because "make the cost
    /// obvious before it starts" is the difference between a helpful step and
    /// an app that disappears for twenty minutes.
    struct Plan {
        let source: URL
        let destination: URL
        /// ffprobe's `codec_name` for the first stream of each type, or nil
        /// when the container has none.
        let videoCodec: String?
        let audioCodec: String?
        /// Whether that stream can be copied rather than re-encoded.
        let copiesVideo: Bool
        let copiesAudio: Bool
        let width: Int
        let height: Int
        let fps: Double
        let duration: Double
        let sourceBytes: Int64
        /// The first video stream's `r_frame_rate`; nil when it is not two
        /// positive integers.
        let videoRate: FrameRate?

        /// The one plan written as MP4, snapped to its frame rate and checked
        /// before it is kept (spec §11 #227).
        var copiesVP9: Bool { copiesVideo && videoCodec == "vp9" }

        /// This plan with the video re-encoded: what a VP9 copy that failed
        /// falls back to. The sound is decided again, for a QuickTime file.
        func reencodingVideo() -> Plan {
            Plan(
                source: source, destination: destination, videoCodec: videoCodec,
                audioCodec: audioCodec, copiesVideo: false,
                copiesAudio: audioCodec.map { FFmpegRewrap.copyableAudio.contains($0) } ?? true,
                width: width, height: height, fps: fps, duration: duration,
                sourceBytes: sourceBytes, videoRate: videoRate)
        }

        /// No re-encoding at all: the fast, lossless case, and the one this
        /// feature exists for.
        var isStreamCopy: Bool { copiesVideo && copiesAudio }

        /// Roughly what the result will weigh. A copy is the source's own
        /// size; an encode is estimated at 0.12 bits per pixel per frame plus
        /// the AAC bitrate, which is the right order of magnitude for the
        /// x264 CRF used below and is presented as "about", never as fact.
        var estimatedBytes: Int64 {
            if copiesVideo { return sourceBytes }
            let pixels = Double(max(1, width * height))
            let rate = fps > 0 ? fps : 30
            let bitsPerSecond = pixels * rate * 0.12 + (copiesAudio ? 0 : 256_000)
            let seconds = duration > 0 ? duration : 0
            return Int64((bitsPerSecond * seconds / 8).rounded())
        }

        /// The sentence the user reads before deciding. Names the codec that
        /// forced the choice, so "why is this one slow and that one instant"
        /// has an answer on screen.
        var consentText: String {
            let size = ByteCountFormatter.string(fromByteCount: estimatedBytes, countStyle: .file)
            let tail =
                "\n\nThe original file is left exactly where it is; Frame Job imports the "
                + "converted copy from its Application Support folder."
            if isStreamCopy {
                return "\(source.lastPathComponent) is in a container AVFoundation will not open, "
                    + "but the \(codecList) inside it can be decoded as they are. ffmpeg can "
                    + "repackage it into a QuickTime movie by copying the streams — no "
                    + "re-encoding, no loss of quality, about \(size) and a few seconds."
                    + tail
            }
            if copiesVideo {
                // `copiesVideo` is also true when there is no picture at all
                // — an audio-only Matroska — and promising to copy a video
                // stream that does not exist would be a small lie.
                let sound = "\(audioCodec ?? "audio") soundtrack has to be re-encoded to AAC"
                let middle = videoCodec == nil
                    ? "The \(sound)"
                    : "The video can be copied as it is, but the \(sound)"
                return "\(source.lastPathComponent) is in a container AVFoundation will not open. "
                    + "\(middle). About \(size), and a few seconds."
                    + tail
            }
            return "\(source.lastPathComponent) is \(videoCodec ?? "in a format") this Mac cannot "
                + "decode, so repackaging is not enough — the whole file has to be re-encoded to "
                + "H.264. That is \(sizeLine) of video and takes at least as long as the clip "
                + "runs, usually longer. The result will be about \(size)."
                + tail
        }

        private var codecList: String {
            switch (videoCodec, audioCodec) {
            case (let video?, let audio?): return "\(video) video and \(audio) audio"
            case (let video?, nil): return "\(video) video"
            case (nil, let audio?): return "\(audio) audio"
            case (nil, nil): return "streams"
            }
        }

        private var sizeLine: String {
            let seconds = Int(duration.rounded())
            let clock = String(format: "%d:%02d", seconds / 60, seconds % 60)
            guard width > 0, height > 0 else { return clock }
            return "\(width)×\(height), \(clock)"
        }
    }

