            let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil)
                as? [CFString: Any],
            let depth = (properties[kCGImagePropertyDepth] as? NSNumber)?.intValue
        else { return false }
        return depth > 8
    }

